package com.bank.overlap.service;

import com.bank.overlap.dto.OverlapResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class OverlapService {

    public OverlapResult findOverlap(List<String> listA, List<String> listB) {
        // Convert to HashSet for O(1) lookups
        Set<String> setA = new HashSet<>(listA);
        Set<String> setB = new HashSet<>(listB);

        // ═══ INTERSECTION: common elements ═══
        List<String> common = listA.stream()
            .filter(setB::contains)       // O(1) lookup in HashSet
            .distinct()                    // remove duplicates from listA
            .sorted()
            .toList();

        // ═══ DIFFERENCE: only in A ═══
        List<String> onlyA = listA.stream()
            .filter(s -> !setB.contains(s))
            .distinct().sorted().toList();

        // ═══ DIFFERENCE: only in B ═══
        List<String> onlyB = listB.stream()
            .filter(s -> !setA.contains(s))
            .distinct().sorted().toList();

        // ═══ OVERLAP PERCENTAGE ═══
        Set<String> union = new HashSet<>(setA);
        union.addAll(setB);
        double overlap = union.isEmpty() ? 0 : (double) common.size() / union.size() * 100;

        return new OverlapResult(
            listA.stream().distinct().sorted().toList(),
            listB.stream().distinct().sorted().toList(),
            common, onlyA, onlyB, Math.round(overlap * 10.0) / 10.0);
    }
}
