package com.bank.overlap.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class IntersectionTest {

    @Test
    void basicIntersection() {
        Set<String> setB = new HashSet<>(List.of("TCS", "WIPRO", "HDFC"));
        List<String> common = List.of("RELIANCE", "TCS", "HDFC", "INFY").stream()
            .filter(setB::contains).distinct().sorted().toList();
        assertThat(common).containsExactly("HDFC", "TCS");
    }

    @Test
    void noOverlap() {
        Set<String> setB = new HashSet<>(List.of("WIPRO", "BAJAJ"));
        List<String> common = List.of("RELIANCE", "TCS").stream()
            .filter(setB::contains).toList();
        assertThat(common).isEmpty();
    }

    @Test
    void completeOverlap() {
        Set<String> setB = new HashSet<>(List.of("A", "B", "C"));
        List<String> common = List.of("A", "B", "C").stream()
            .filter(setB::contains).toList();
        assertThat(common).containsExactly("A", "B", "C");
    }

    @Test
    void distinctRemovesDuplicatesInIntersection() {
        Set<String> setB = new HashSet<>(List.of("TCS"));
        List<String> common = List.of("TCS", "TCS", "TCS").stream()
            .filter(setB::contains).distinct().toList();
        assertThat(common).containsExactly("TCS");  // not 3 times!
    }

    @Test
    void hashSetGivesO1Lookups() {
        // List.contains = O(n), HashSet.contains = O(1)
        List<String> largeList = new ArrayList<>();
        for (int i = 0; i < 100000; i++) largeList.add("ITEM-" + i);
        Set<String> largeSet = new HashSet<>(largeList);

        // HashSet lookup is instant even for 100K elements
        assertThat(largeSet.contains("ITEM-99999")).isTrue();
        assertThat(largeSet.contains("NONEXISTENT")).isFalse();
    }
}
